// A single push can carry many lines, so every incoming item is batched into one
// request rather than one HTTP call per message. Loki addresses entries by label set,
// so items sharing the same labels collapse into the same stream.
const streams = new Map();
const now = Date.now();

$input.all().forEach((item, index) => {
  const input = item.json;
  const data = input.data ?? {};

  // Labels are indexed and each combination creates a stream, so they must stay
  // low-cardinality. Never put an id in here - that is what structured metadata is for.
  const stream = {
    service_name: 'n8n',
    severity: String(input.severity),
  };

  // Structured metadata is stored per line and is queryable, but never creates a stream.
  // This is where the ids belong. `execution_id` is what Grafana joins to Tempo on, and
  // `root_execution_id` keeps every line of one email chain tied to the orchestrator run.
  const metadata = {};
  const metadataCandidate = {
    execution_id: input.execution_id,
    root_execution_id: input.root_execution_id || input.execution_id,
    ...data,
  };
  for (const [key, value] of Object.entries(metadataCandidate)) {
    if (value == null || value === '' || typeof value === 'object') continue;
    metadata[key] = String(value);
  }

  const line = input.message;

  // Loki timestamps are nanoseconds.
  // The whole batch shares a millisecond, so the item index fills the microseconds - a stream silently drops lines that repeat a timestamp.
  const timestamp = `${now}${String(index).padStart(6, '0')}`;

  const key = JSON.stringify(stream);
  if (!streams.has(key)) streams.set(key, { stream, values: [] });
  streams.get(key).values.push([timestamp, line, metadata]);
});

// Nothing to log means nothing to send - returning no items keeps the HTTP node idle.
if (streams.size === 0) return [];

return [{ json: { streams: [...streams.values()] } }];
